  <style>
    @font-face {
      font-family: 'Gotham';
      src: url("64dd9348-c72c-4738-b939-63674f1ba8c6") format('opentype'); /* bundled */
      font-weight: 400;
      font-style: normal;
      font-display: swap;
    }
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { scroll-behavior: smooth; }
    body { background: #f3f1ee; font-family: 'Gotham', 'Helvetica Neue', sans-serif; color: #292620; -webkit-font-smoothing: antialiased; }
    #root { padding-top: 80px; }
    .page { animation: fadeIn 0.35s ease; }
    @keyframes fadeIn { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }

    /* Tweaks panel */
    #tweaks-panel {
      display: none;
      position: fixed;
      bottom: 24px; right: 24px;
      width: 260px;
      background: #1e1c18;
      border-radius: 4px;
      padding: 20px;
      z-index: 9999;
      box-shadow: 0 8px 32px rgba(0,0,0,0.4);
      font-family: 'Gotham', 'Helvetica Neue', sans-serif;
    }
    #tweaks-panel.open { display: block; }
    #tweaks-panel h4 { font-size: 10px; font-weight: 400; letter-spacing: 0.2em; text-transform: uppercase; color: #c8b096; margin-bottom: 16px; }
    .tweak-row { margin-bottom: 14px; }
    .tweak-label { font-size: 10px; font-weight: 300; letter-spacing: 0.12em; text-transform: uppercase; color: #7a736b; display: block; margin-bottom: 6px; }
    .tweak-select { width: 100%; background: #292620; border: 1px solid #33312c; border-radius: 2px; color: #f3f1ee; font-family: 'Gotham', 'Helvetica Neue', sans-serif; font-size: 12px; padding: 8px 10px; outline: none; cursor: pointer; }
    .tweak-toggle { display: flex; gap: 6px; }
    .tweak-toggle button { flex: 1; padding: 7px; font-family: 'Gotham', 'Helvetica Neue', sans-serif; font-size: 10px; letter-spacing: 0.1em; text-transform: uppercase; border: 1px solid #33312c; background: #292620; color: #7a736b; border-radius: 2px; cursor: pointer; transition: all 0.15s; }
    .tweak-toggle button.active { background: #c8b096; color: #fff; border-color: #c8b096; }

    /* Contact & Services pages */
    .contact-section { background: #f3f1ee; padding: 100px 64px; display: grid; grid-template-columns: 1fr 1fr; gap: 80px; align-items: start; max-width: 1200px; margin: 0 auto; }
    .form-group { margin-bottom: 20px; }
    .form-label { font-size: 10px; font-weight: 400; letter-spacing: 0.15em; text-transform: uppercase; color: #7a736b; display: block; margin-bottom: 8px; }
    .form-input { width: 100%; border: 1px solid #e4e0db; border-radius: 2px; padding: 13px 16px; font-family: 'Gotham', 'Helvetica Neue', sans-serif; font-size: 14px; font-weight: 300; color: #292620; background: #FAFAF8; outline: none; transition: border-color 0.2s; }
    .form-input:focus { border-color: #c8b096; }
    .form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
    .form-textarea { resize: vertical; min-height: 100px; }
    .services-full { background: #f3f1ee; padding: 100px 64px; }
    .services-grid-full { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2px; }

    /* ── RESPONSIVE ─────────────────────────────────────── */
    /* Nav mobile */
    .mob-menu-btn { display: none; background: none; border: none; cursor: pointer; padding: 8px; }
    .mob-menu-btn-wrap { display: none !important; }
    .mob-book-btn { display: block; }
    .mob-menu-btn span { display: block; width: 22px; height: 1.5px; background: #f3f1ee; margin: 5px 0; transition: all 0.2s; }
    .mob-nav { display: none; position: fixed; top: 80px; left: 0; right: 0; background: #292620; z-index: 199; padding: 24px 32px 32px; border-top: 1px solid rgba(255,255,255,0.06); }
    .mob-nav.open { display: flex; flex-direction: column; gap: 0; }
    .mob-nav a { font-family: 'Gotham','Helvetica Neue',sans-serif; font-size: 13px; font-weight: 400; letter-spacing: 0.12em; text-transform: uppercase; color: #9e978f; padding: 14px 0; border-bottom: 1px solid rgba(255,255,255,0.05); cursor: pointer; display: block; }
    .mob-nav a:last-child { border-bottom: none; }
    .nav-links-desktop { display: flex; gap: 20px; align-items: center; }
    .nav-contact-strip { display: flex; gap: 16px; align-items: center; }

    /* Section padding */
    .resp-section { padding: 80px 64px; }

    /* Two-col grids → single col on mobile */
    .grid-2col { display: grid; grid-template-columns: 1fr 1fr; gap: 80px; align-items: center; }
    .grid-3col { display: grid; grid-template-columns: repeat(3,1fr); gap: 2px; }
    .grid-4col { display: grid; grid-template-columns: repeat(4,1fr); gap: 24px; }
    .grid-3col-reviews { display: grid; grid-template-columns: repeat(3,1fr); gap: 2px; }
    .footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 48px; }

    @media (max-width: 1024px) {
      .grid-4col { grid-template-columns: repeat(2,1fr); }
      .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
      .nav-links-desktop { gap: 14px; }
    }

    @media (max-width: 1400px) {
      .mob-menu-btn { display: block; }
      .mob-menu-btn-wrap { display: flex !important; align-items: center; }
      .nav-links-desktop { display: none; }
    }

    @media (max-width: 768px) {
      #root { padding-top: 64px; }
      .nav-contact-strip { display: none; }
      .mob-book-btn { display: none; }
      nav { padding: 0 24px !important; height: 64px !important; }
      .resp-section { padding: 56px 24px !important; }
      .grid-2col { grid-template-columns: 1fr !important; gap: 40px !important; }
      .grid-3col { grid-template-columns: 1fr !important; }
      .grid-4col { grid-template-columns: 1fr 1fr !important; gap: 16px !important; }
      .grid-3col-reviews { grid-template-columns: 1fr !important; }
      .footer-grid { grid-template-columns: 1fr !important; gap: 32px !important; }
      .contact-section { grid-template-columns: 1fr !important; padding: 56px 24px !important; gap: 40px !important; }
      .form-row { grid-template-columns: 1fr !important; }
      .services-full { padding: 56px 24px !important; }
      .services-grid-full { grid-template-columns: 1fr !important; }
      .hero-h1 { font-size: 48px !important; }
      .hero-section { padding: 100px 24px 60px !important; min-height: auto !important; }
      .hero-img { display: none !important; }
      .hero-stats { left: 24px !important; gap: 16px !important; }
      .hero-stat-num { font-size: 22px !important; }
      .about-img-block { display: none !important; }
      .trust-bar { padding: 20px 24px !important; gap: 24px !important; }
      .section-heading { font-size: 32px !important; }
      .footer-wrap { padding: 48px 24px 32px !important; }
      .mob-nav { top: 64px; }
      .office-photo-block { height: 260px !important; }
    }

    @media (max-width: 480px) {
      .grid-4col { grid-template-columns: 1fr !important; }
      .hero-h1 { font-size: 38px !important; }
      .section-heading { font-size: 28px !important; }
    }
  </style>























