<body>
<div id="root"></div>

<div id="tweaks-panel">
  <h4>Tweaks</h4>
  <div class="tweak-row">
    <span class="tweak-label">Hero Style</span>
    <div class="tweak-toggle" id="hero-toggle">
      <button class="active" data-val="dark" onclick="setTweak('heroStyle','dark',this)">Dark</button>
      <button data-val="light" onclick="setTweak('heroStyle','light',this)">Light</button>
      <button data-val="split" onclick="setTweak('heroStyle','split',this)">Split</button>
    </div>
  </div>
  <div class="tweak-row">
    <span class="tweak-label">Trust Bar</span>
    <div class="tweak-toggle" id="trust-toggle">
